# Signal mssgbox
class signal_mssgbox(QObject):
    signal = pyqtSignal(str,int)
    return_nmap_user_select:str = None
    return_gobuster_user_select:str = None
    
    def __init__(self):
        super().__init__()
        self.signal.connect(self.check_signal)
        
    def check_signal(self,check_parameter,db_id):
        if check_parameter == "Done_wait_Nikto": #nikto not ok
            QMessageBox.information(MainWindow, 'Information Message Box', 'Nmap, Whatweb and Gobuster Scanning is finished', QMessageBox.Close)
        elif check_parameter == "Done":
            # Display Successful msgbox #all ok
            QMessageBox.information(MainWindow, 'Information Message Box', 'Scanning is finished', QMessageBox.Close)
        elif check_parameter == "nmap_port":
            # Ask User choose port
            namp_record_port_list = []
            nmap_records = DB_connect.get_one_tool_result(id=db_id,tool_name="nmap")
            for record in nmap_records:
                if record.get("target_address", None) != None and record.get("portid", None) != None:
                    namp_record_port_list.append(record['portid'])
            selected_portid, ok_btn = QInputDialog.getItem(MainWindow,'please select targer server portid', 'portid:',namp_record_port_list,0,False)
            if ok_btn:
                for record in nmap_records:
                    if record.get("portid",None) == selected_portid:
                        selected_target_address = record['target_address']
                signal_mssgbox.return_nmap_user_select = selected_target_address
                return selected_target_address
            else:
                signal_mssgbox.return_nmap_user_select = nmap_records[0]['target_address']
                return nmap_records[0]['target_address']
        elif check_parameter == "Gobuster_wordlist":
            user_reply = QMessageBox.question(MainWindow, "Question", "Do you want to choose the wordlist?", QMessageBox.Yes | QMessageBox.No)
            whatweb_status = False
            # #Get whatweb recommend wordlist 
            whatweb_recommend_wordlist = DB_connect.get_one_tool_result(id=db_id,tool_name="whatweb")
            num_of_whatweb_result = len(whatweb_recommend_wordlist)
            if num_of_whatweb_result > 0: 
                whatweb_status = True
                wordlist = whatweb_recommend_wordlist[0]['wordlist']
                
            if user_reply == QMessageBox.Yes:# ask user select wordlist
                wordlist_dict = {'wordpress':f"{os.path.dirname(__file__)}/Wordlists/CMS/wordpress.txt",
                                 'drupal':f"{os.path.dirname(__file__)}/Wordlists/CMS/drupal.txt",
                                 'common':f"{os.path.dirname(__file__)}/Wordlists/common.txt"}
                wordlist_name = wordlist_dict.keys()
                
                seleced_key, ok_btn = QInputDialog.getItem(MainWindow,'please select wordlist', 'wordlist:',wordlist_name,0,False)
                if ok_btn:
                    signal_mssgbox.return_gobuster_user_select = wordlist_dict[seleced_key]#User choose wordlist
                    return wordlist_dict[seleced_key]
                else:
                    if whatweb_status == True: # if whatweb have result
                        signal_mssgbox.return_gobuster_user_select = wordlist#By Default wordlist
                        return wordlist
                    else: # if whatweb no result
                        signal_mssgbox.return_gobuster_user_select = f"{os.path.dirname(__file__)}/Wordlists/common.txt" #By Default wordlist
                        return f"{os.path.dirname(__file__)}/Wordlists/common.txt"
            else: #if NO
                if whatweb_status == True: # if whatweb have result
                    signal_mssgbox.return_gobuster_user_select = wordlist#By Default wordlist
                    return wordlist
                else: # if whatweb no result
                    signal_mssgbox.return_gobuster_user_select = f"{os.path.dirname(__file__)}/Wordlists/common.txt" #By Default wordlist
                    return f"{os.path.dirname(__file__)}/Wordlists/common.txt"
        elif check_parameter == "Gobuster_dir":
            QMessageBox.information(MainWindow, 'Information Message Box', 'If you think the results of directory scan might contain other contents,\n you can take that directory to scan again (on Gobuster only).', QMessageBox.Close)
            pass
        pass

    pass
