    #button call starting scan function
    def call_tool(self):
        if self.txt_target.text() == "":
            #Error Msg Box
            QMessageBox.warning(MainWindow, 'Error Message Box', 'You must input a IP/URL into the target box!', QMessageBox.Close)
            return False
        
        self.call_signal = signal_mssgbox()
        
        #Do the thread for scanning
        thread_scan = threading.Thread(target=self.start_tool_scan)
        thread_scan.start()
        self.tabw_main.setCurrentIndex(2)
        pass

    #Use the thread to start scanning
    def start_tool_scan(self):
        
        # Show the Loading bar
        self.pb.show()
        self.btn_scan.setDisabled(True)
        self.btn_gobuster_dir_wordlist_filter.setDisabled(True)
        self.btn_exit.setDisabled(True)
        # Check User config setting 
        self.config = {
            'Nmap':{"open":0} ,
            'WhatWeb':{"open":0},
            'Gobuster':{"open":0,"mode":"dir"},
            'Nikto':{"open":0}
            }
        
        # Reset the scanning state
        self.lbl_scan_status_nmap_var.setText("Disable")
        self.lbl_scan_status_whatweb_var.setText("Disable")
        self.lbl_scan_status_gobuster_var.setText("Disable")
        self.lbl_scan_status_nikto_var.setText("Disable")
        
        self.lbl_scan_status_nmap_var.setStyleSheet("background-color: rgb(46, 218, 255);")
        self.lbl_scan_status_whatweb_var.setStyleSheet("background-color: rgb(46, 218, 255);")
        self.lbl_scan_status_gobuster_var.setStyleSheet("background-color: rgb(46, 218, 255);")
        self.lbl_scan_status_nikto_var.setStyleSheet("background-color: rgb(46, 218, 255);")
        
        # Set the Default mode setting
        if self.chk_dmode.isChecked() == True:
            self.config = {
                'Nmap':{"open":1} ,
                'WhatWeb':{"open":1},
                'Gobuster':{"open":1,"mode":"dir"},
                'Nikto':{"open":1}
                }
        # set the user setting
        elif self.chk_dmode.isChecked() == False:
            if self.chk_nmap_run.isChecked() == True:
                self.config['Nmap'] = {"open":1}
            if self.chk_whatweb_run.isChecked() == True:
                self.config['WhatWeb'] = {"open":1}
            if self.chk_gobuster_run.isChecked() == True:
                self.config['Gobuster'] = {"open":1}
                if self.btn_gobuster_mode_dir.isChecked() == True:
                    self.config['Gobuster'] = {"open":1,"mode":"dir"}
                elif self.btn_gobuster_mode_subdomain.isChecked() == True:
                    self.config['Gobuster'] = {"open":1,"mode":"subdomain"}
                elif self.btn_gobuster_mode_vhost.isChecked() == True:
                    self.config['Gobuster'] = {"open":1,"mode":"vhost"}
            if self.chk_nikto_run.isChecked() == True:
                self.config['Nikto'] = {"open":1}
                pass
            pass

        # Do Scanning(Nmap, Gobuster, Whatweb, Nikto)
        self.list_raw_scan_result = list()
        
        self.scan = tools.Scan(url=self.txt_target.text(), tools_config=self.config, user_agent=self.switch_user_agnet())
        
        self.scan.main()
        self.current_DB_id = self.scan.get_current_DB_id()
        
        #Nmap Scan
        if self.config['Nmap']['open'] == 1:
            self.lbl_scan_status_nmap_var.setText("Scanning...")
            self.lbl_scan_status_nmap_var.setStyleSheet("background-color: rgb(255, 0, 0);")
            
            #start the nmap scan
            self.nmap_raw_result = self.scan.tools_nmap()
            
            pprint_raw_result = pprint.pformat(self.nmap_raw_result)
            lines_raw_result = pprint_raw_result.splitlines()
            text = '\n'.join(pprint_raw_result.splitlines())
            self.list_raw_scan_result.append(text)
                
            # Display the raw result 
            self.display_raw_result_in_lbl_result_raw()
            
            
            self.lbl_scan_status_nmap_var.setText("Scanning Completed!!!")
            self.lbl_scan_status_nmap_var.setStyleSheet("background-color: rgb(0, 255, 0);")
            self.height_setting()

            self.nmap_scan_all_result = DB_connect.get_one_tool_result(id=self.current_DB_id,tool_name="nmap")
            all_port_target_address_list = []    
            
            for record in self.nmap_scan_all_result:
                try:
                    all_port_target_address_list.append(record["target_address"])
                except:
                    pass
            
            # User choose Port
            if len(self.nmap_scan_all_result) > 1:
                self.call_signal.signal.emit("nmap_port",self.current_DB_id)
                time.sleep(1)
                while signal_mssgbox.return_nmap_user_select not in all_port_target_address_list:
                    time.sleep(2)
                    pass
                else:
                    nmap_list = [{'url': signal_mssgbox.return_nmap_user_select}]
                    self.scan.choose_nmap_web_server_dict_list(nmap_list)
                    pass
                    

        elif self.config['Nmap']['open'] == 0:
            self.scan.tools_nmap()
            pass
        
        #Thread Nikto Scan
        thread_nikto = threading.Thread(target=self.thread_nikto_scan)
        thread_nikto.start()
        
        #Whatweb Scan
        if self.config['WhatWeb']['open'] == 1:
            self.lbl_scan_status_whatweb_var.setText("Scanning...")
            self.lbl_scan_status_whatweb_var.setStyleSheet("background-color: rgb(255, 0, 0);")
            
            # Start the whatweb scan
            self.whatweb_raw_result = self.scan.tools_whatweb()
            
            # Set the raw resulrt label and scroll bar height number
            for loop in self.whatweb_raw_result:
                self.list_raw_scan_result.append(loop)
            
            # Display the raw result    
            self.display_raw_result_in_lbl_result_raw()
            
            self.lbl_scan_status_whatweb_var.setText("Scanning Completed!!!")
            self.lbl_scan_status_whatweb_var.setStyleSheet("background-color: rgb(0, 255, 0);")
            self.height_setting()
            
            pass
        elif self.config['WhatWeb']['open'] == 0:
            self.scan.tools_whatweb()
            pass
        
        #Gobuster Scan
        if self.config['Gobuster']['open'] == 1:
            if self.config['Gobuster']['mode'] == "dir":
                self.call_signal.signal.emit("Gobuster_wordlist",self.current_DB_id)
                time.sleep(1)
                while signal_mssgbox.return_gobuster_user_select is None:
                    time.sleep(2)
                else:
                    self.scan.choose_gobuster_dir_wordlist(signal_mssgbox.return_gobuster_user_select)
                    pass
            
            self.lbl_scan_status_gobuster_var.setText("Scanning...")
            self.lbl_scan_status_gobuster_var.setStyleSheet("background-color: rgb(255, 0, 0);")
            
            # Start the gobuster scan
            self.gobuster_result_list, self.gobuster_raw_result = self.scan.tools_gobuster()
            
            if self.config['Gobuster']['mode'] == "dir":
                self.call_signal.signal.emit("Gobuster_dir",self.current_DB_id)
            
            # Set the raw resulrt label and scroll bar height number
            for loop in self.gobuster_raw_result:
                self.list_raw_scan_result.append(loop)
                
            # Display the raw result
            self.display_raw_result_in_lbl_result_raw()
            
            self.lbl_scan_status_gobuster_var.setText("Scanning Completed!!!")
            self.lbl_scan_status_gobuster_var.setStyleSheet("background-color: rgb(0, 255, 0);")
            
            pass
        elif self.config['Gobuster']['open'] == 0:
            self.scan.tools_gobuster()
            pass
        pass
        
        self.btn_scan.setDisabled(False)
        self.btn_gobuster_dir_wordlist_filter.setDisabled(False)
        self.btn_exit.setDisabled(False)
        self.height_setting()
        self.pb.hide()
        if self.lbl_scan_status_nikto_var.text() == "Scanning...":
            self.call_signal.signal.emit("Done_wait_Nikto",self.current_DB_id)
        else:
            self.call_signal.signal.emit("Done",self.current_DB_id)
        pass
    
    def thread_nikto_scan(self):
        #Nikto Scan
        if self.config['Nikto']['open'] == 1:
            self.lbl_scan_status_nikto_var.setText("Scanning...")
            self.lbl_scan_status_nikto_var.setStyleSheet("background-color: rgb(255, 0, 0);")
            
            self.nikto_raw_result = self.scan.tools_nikto()
            
            # Display Nikto raw result in the label lbl_result_raw_nikto
            result = ""
            for loop in self.nikto_raw_result:
                result += f"{loop}"
                self.lbl_result_raw_nikto.setText(result)
            pass
            
            self.lbl_scan_status_nikto_var.setText("Scanning Completed!!!")
            self.lbl_scan_status_nikto_var.setStyleSheet("background-color: rgb(0, 255, 0);")
            self.height_setting()
        
    
    # Set the raw resulrt label and scroll bar height
    def height_setting(self):
        self.lbl_result_raw.adjustSize()
        self.lbl_result_raw_nikto.adjustSize()
        self.raw_topFiller.adjustSize()
            
    # Display Nmap, Whatweb and Gobuster raw result in the label lbl_result_raw
    def display_raw_result_in_lbl_result_raw(self):
        result = ""
        for loop in self.list_raw_scan_result:
                result += f"{loop}\n"
                self.lbl_result_raw.setText(result)
        pass
        
