    def switch_user_agnet(self):
        selected = self.cmb_user_agent.currentText()
        if selected == "Safari":
            return "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/112.0.0.0 Safari/537.36"
        elif selected == "Firefox":
            return "Mozilla/5.0 (Macintosh; Intel Mac OS X 13.3; rv:112.0) Gecko/20100101 Firefox/112.0"
        elif selected == "Gecko":
            return "Mozilla/5.0 (Windows NT 10.0; Trident/7.0; rv:11.0) like Gecko"
        elif selected == "Ramdom Normal Browser":
            return "random_normal_browser"
        elif selected == "FYP tools":
            return "FYP_tools"
        else:
            print("switch_user_agnet Error, use default user-agent")
            return "FYP_tool"
    
