    def result_sqlmap_table_update(self):
        num_of_item = self.result_cmb_sqlmap.currentText()
        num_of_item = num_of_item.split(" : ")
        num_of_item = int(num_of_item[0])
        
        if len(self.sqlmap_all_data_list) != 0:
            select_item_dict = self.sqlmap_all_data_list[num_of_item]
            if select_item_dict['datatype'] == 'columns':
                self.result_sqlmap_table.setRowCount(len(select_item_dict['result']))
                self.result_sqlmap_table.setColumnCount(2)
                self.result_sqlmap_table.setHorizontalHeaderLabels(select_item_dict['result'].keys())
                # if "result" in select_item_dict:
                row = 0
                for key in select_item_dict['result']:
                    self.result_sqlmap_table.setItem(row,0,QTableWidgetItem(key))
                    self.result_sqlmap_table.setItem(row,1,QTableWidgetItem(select_item_dict['result'][key]))
                    row = row + 1
            elif select_item_dict['datatype'] == 'record':  
                self.result_sqlmap_table.setRowCount(len(select_item_dict['result']))
                self.result_sqlmap_table.setColumnCount(len(select_item_dict['result'][0]))
                self.result_sqlmap_table.setHorizontalHeaderLabels(select_item_dict['result'][0].keys())
