    def update_result_nikto_table(self):
        all_data_list=self.result_nikto_table_data_list 
        display_data_list = list()
        #get filter or raw data
        if len(all_data_list) != 0:
            if self.result_Nikto_chk_raw.isChecked() == True:
                for item in all_data_list:
                    if item.get("type","") == "raw":
                        if item.get("result", None) != None:
                            display_data_list.append(item['result'])
            else:
                for item in all_data_list:
                    if item.get("type","") == "filtered":
                        if item.get("result", None) != None:
                            display_data_list.append(item['result'])
        
        self.result_Nikto_table.setColumnCount(1)
        self.result_Nikto_table.setRowCount(len(display_data_list))
        self.result_Nikto_table.setColumnWidth(0, 800)
        row = 0
        for line in display_data_list:
            self.result_Nikto_table.setItem(row, 0, QTableWidgetItem(line.replace("\n","")))
            row = row + 1 

    def update_result_xsstrike(self):
        if self.xsstrike_all_data_list:
            selected_text = self.cmb_xsstrike_event_select.currentText()
            selected_text = selected_text.split(" | ",1)
            try:
                selected_number = int(selected_text[0]) - 1
            except:
                print("update_result_xsstrike Error")
            selected_data = self.xsstrike_all_data_list[selected_number]

            #updata lable and table
            self.lbl_xsstrike_cookie_info_var.setText(selected_data.get('cookie_info','not found in database'))
            if selected_data.get('result',None) != None:
                self.table_xsstrike.setColumnCount(1)
                self.table_xsstrike.setRowCount(len(selected_data['result']))
                self.table_xsstrike.setColumnWidth(0, 560)
                self.table_xsstrike.setHorizontalHeaderLabels(["possible payload"])
                row = 0
                for line in selected_data['result']:
                    self.table_xsstrike.setItem(row,0,QTableWidgetItem(line) )
                    row = row + 1
        pass

    def update_result_page(self,id=""):
        if id == "":
            try:
                id = self.current_DB_id
            except:
                print("current DB ID not found")
        result_dict = DB_connect.get_record_for_result_page(id)

        # for tab_page_number in range(1, 6): #disable page


        if len(result_dict) != 0:
            result_receivedData_exist_tools_list = result_dict.get("result_exist_tools_list","")
            self.lbl_Domain_var.setText(result_dict.get("target_url",""))
            self.lbl_datetime_var.setText(result_dict.get("date_time",""))
            self.lbl_id_var.setText(id)
            page_num_dict = {'namp':1,'whatweb':2,"gobuster":3,"nikto":4,"sqlmap":5,"xsstrike":6}
            for tool_key in page_num_dict:
                if tool_key not in result_receivedData_exist_tools_list:
                    self.result_tab.setTabEnabled(page_num_dict[tool_key],False)
            #clear whatweb_lable
            self.result_lbl_whatweb_target_url_var.setText('')
            self.result_lbl_whatweb_web_server_var.setText('')
            self.result_lbl_whatweb_OS_var.setText('')
            tools_config_dict = result_dict.get("tools_config",{})
            if len(tools_config_dict) != 0:
                ## tools config page
                self.table_result_tools_config_info.setRowCount(len(tools_config_dict))
                self.table_result_tools_config_info.setColumnCount(3)
                self.table_result_tools_config_info.setHorizontalHeaderLabels(['Tools','Status','Other'])
                self.table_result_tools_config_info.setColumnWidth(2,250)
                x = 0
                for line in tools_config_dict:
                    self.table_result_tools_config_info.setItem(x,0,QTableWidgetItem(line))
                    if tools_config_dict[line].get("open") == 1:
                        status = "enable"
                    elif tools_config_dict[line].get("open") == 0:
                        status = "disable"
                    else:
                        status = "unkwon"
                    self.table_result_tools_config_info.setItem(x,1,QTableWidgetItem(status))
                    
                    other_info = ""
                    for data_key in tools_config_dict[line]:
                        if data_key != "open":
                            other_info = other_info + f"'{data_key}'={tools_config_dict[line][data_key]}"

                    self.table_result_tools_config_info.setItem(x,2,QTableWidgetItem(other_info))
                    x = x+1
            # print(result_dict)
            if "nmap" in result_receivedData_exist_tools_list:
                self.result_tab.setTabEnabled(1,True) #enable tab
                data_list = DB_connect.get_one_tool_result(id=id,tool_name="nmap")
                
                if len(data_list) != 0:
                    key_list = list()
                    for key in data_list[0]:
                        if key != "tools":
                            key_list.append(key)
                    self.table_result_namp_info.setRowCount(len(data_list))
                    self.table_result_namp_info.setColumnCount(len(data_list[0])-1)
                    self.table_result_namp_info.setHorizontalHeaderLabels(key_list)
                    self.table_result_namp_info.setColumnWidth(0,160)
                    x = 0
                    for item in data_list:
                        y = 0
                        for key in item:
                            if key != "tools":
                                self.table_result_namp_info.setItem(x,y,QTableWidgetItem(item[key]))
                                y = y+1
                        x = x + 1
                # print(data_list)
                pass
            if "whatweb" in result_receivedData_exist_tools_list:
                self.result_tab.setTabEnabled(2,True)
                self.whatweb_result_data_list = DB_connect.get_one_tool_result(id=id,tool_name="whatweb")
                num_of_item = 1
                self.result_cmb_whatweb_url.clear()
                for item in self.whatweb_result_data_list:
                    self.result_cmb_whatweb_url.addItem(f"{num_of_item} : {item.get('target_url')}")
                self.result_btn_whatweb_display.clicked.connect(self.result_tab_whatweb_select_url_select)
                pass
            if "gobuster" in result_receivedData_exist_tools_list:
                self.result_btn_gobuster_open_page.hide()
                self.result_btn_gobuster_open_page.setDisabled(True)
                self.result_tab.setTabEnabled(3,True)
                gobuster_list = DB_connect.get_one_tool_result(id=id,tool_name="gobuster")
                if len(gobuster_list) != 0 :
                    self.result_lbl_gobuster_mode_var.setText(gobuster_list[0].get('mode',"unkwon"))
                    self.result_lbl_gobuster_wordlist_var.setText(gobuster_list[0].get('used_wordlist',"unkwon"))
